      "customfield_10231": {
        "value": {
          "type": "doc",
          "version": 1,
          "content": [
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "3341a0b5f5b5"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "676adabf22e2"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given country-to-currency mappings are configured in SFCC, when a Shopper lands on a domestic storefront, then prices are served from the pricebook configured for that storefront's base currency."
                        }
                      ],
                      "attrs": {
                        "localId": "50e5a9bcafe4"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "c6eeb7c6ca6b"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a Shopper on a Global-e storefront has a session currency set by Global-e, when they browse the catalogue, then SFCC loads the pricebook matching that session currency and prices are displayed accordingly."
                        }
                      ],
                      "attrs": {
                        "localId": "4185680b3a7f"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "c9b43015708a"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a Shopper's session currency changes (e.g. they change their ship-to country), when the storefront reloads, then SFCC loads the correct pricebook for the new currency and prices update accordingly."
                        }
                      ],
                      "attrs": {
                        "localId": "79ca3a3840ea"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "7261de8b41ee"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a Site Admin navigates to the country-currency mapping screen in Business Manager, when the screen loads, then they can see the complete list of all configured shipping countries and their mapped target currencies."
                        }
                      ],
                      "attrs": {
                        "localId": "2067473c9c2a"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "07e88a2768e5"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a Site Admin updates a country-to-currency mapping in BM, when the change is saved, then the new mapping takes effect without a code deployment."
                        }
                      ],
                      "attrs": {
                        "localId": "d23e7bab60dd"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "c4cf3e393cd9"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a Business Manager user has a read-only role, when they access the country-currency mapping screen, then they can view but not edit the configured mappings."
                        }
                      ],
                      "attrs": {
                        "localId": "95e712a18c34"
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
