  "customfield_10231": {
    "value": {
      "type": "doc",
      "version": 1,
      "content": [
        {
          "type": "orderedList",
          "attrs": {
            "order": 1,
            "localId": "c97d91023730"
          },
          "content": [
            {
              "type": "listItem",
              "attrs": {
                "localId": "6e7d0a5ed75f"
              },
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "Given a Shopper's active Global-e country is in the configured DDP country list, when the cart renders, then \"Duties and taxes are included in the price displayed\" is shown in the cart."
                    }
                  ],
                  "attrs": {
                    "localId": "595ab9379e53"
                  }
                }
              ]
            },
            {
              "type": "listItem",
              "attrs": {
                "localId": "24f4490dcbfa"
              },
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "Given a Shopper's active Global-e country is in the configured DDU country list, when the cart renders, then no message is shown."
                    }
                  ],
                  "attrs": {
                    "localId": "b4a44b46c311"
                  }
                }
              ]
            },
            {
              "type": "listItem",
              "attrs": {
                "localId": "615beca48c36"
              },
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "Given a Shopper's active country is not in the DDP or DDU list (domestic markets or unlisted countries), when the cart renders, then no duty or tax message is displayed and the surrounding layout is unaffected."
                    }
                  ],
                  "attrs": {
                    "localId": "dcfecd8eb8eb"
                  }
                }
              ]
            },
            {
              "type": "listItem",
              "attrs": {
                "localId": "f6c8f8d15398"
              },
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "Given a country is added to or removed from the DDP or DDU list in Contentful, when the change is published, then the cart reflects the updated list without a code deployment."
                    }
                  ],
                  "attrs": {
                    "localId": "c07c26386c64"
                  }
                }
              ]
            },
            {
              "type": "listItem",
              "attrs": {
                "localId": "9d675c0ad45c"
              },
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "Given the DDP or DDU message text is updated in Contentful, when the change is published, then the updated text is reflected across all applicable countries without a code deployment."
                    }
                  ],
                  "attrs": {
                    "localId": "83dc4db0adb2"
                  }
                }
              ]
            },
            {
              "type": "listItem",
              "attrs": {
                "localId": "06373f808cb8"
              },
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "Given a Shopper views the cart on any device, when the duty/tax message renders, then it displays correctly across desktop, tablet, and mobile breakpoints per Figma specifications."
                    }
                  ],
                  "attrs": {
                    "localId": "8a5b68d722e1"
                  }
                }
              ]
            }
          ]
        }
      ]
    }
  }
}

